import 'i18next'
import type Resources from './resources'

declare module 'i18next' {
  interface CustomTypeOptions {
    defaultNS: 'common'
    // generated by `npx i18next-cli types` (see i18next.config.ts): literal
    // messages, so the ICU arguments of each key can be type-checked
    resources: Resources
    // type t() options and IcuTrans values from the ICU arguments (i18next 26.5.0+)
    parseInterpolation: 'icu'
  }
}
